    "boon-of-spell-recall":[effect("effect.boon-spell-recall","spellcasting.slot.expended","set","boolean","false",{activation:"on_event",trigger:"after casting with a level 1-4 slot when 1d4 equals the slot level",automationLevel:"partial"})],
